CREATE DATABASE IF NOT EXISTS studysync CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE studysync;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS reports,ratings,notifications,study_sessions,group_members,study_groups,messages,study_requests,user_subjects,user_skills,subjects,skills,student_profiles,users;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('student','admin') NOT NULL DEFAULT 'student',status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(role,status)) ENGINE=InnoDB;
CREATE TABLE student_profiles(user_id BIGINT UNSIGNED PRIMARY KEY,college VARCHAR(180) NOT NULL DEFAULT '',course VARCHAR(120) NOT NULL DEFAULT '',semester TINYINT UNSIGNED NULL,about TEXT NULL,learning_goals TEXT NULL,study_mode ENUM('Online','Offline','Both') NULL,availability_days VARCHAR(100) NULL,start_time TIME NULL,end_time TIME NULL,languages VARCHAR(180) NULL,avatar VARCHAR(255) NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE skills(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE subjects(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE user_skills(user_id BIGINT UNSIGNED NOT NULL,skill_id INT UNSIGNED NOT NULL,PRIMARY KEY(user_id,skill_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(skill_id) REFERENCES skills(id)) ENGINE=InnoDB;
CREATE TABLE user_subjects(user_id BIGINT UNSIGNED NOT NULL,subject_id INT UNSIGNED NOT NULL,intent ENUM('help','want') NOT NULL,PRIMARY KEY(user_id,subject_id,intent),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id)) ENGINE=InnoDB;
CREATE TABLE study_requests(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sender_id BIGINT UNSIGNED NOT NULL,receiver_id BIGINT UNSIGNED NOT NULL,message VARCHAR(500) NULL,status ENUM('pending','accepted','rejected','cancelled') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY one_pair(sender_id,receiver_id),INDEX(receiver_id,status),FOREIGN KEY(sender_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(receiver_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE messages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sender_id BIGINT UNSIGNED NOT NULL,receiver_id BIGINT UNSIGNED NOT NULL,message TEXT NOT NULL,is_read TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(sender_id,receiver_id,created_at),FOREIGN KEY(sender_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(receiver_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE study_groups(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(140) NOT NULL,description TEXT NOT NULL,subject_id INT UNSIGNED NULL,topic VARCHAR(120) NULL,level ENUM('Beginner','Intermediate','Advanced') NOT NULL DEFAULT 'Beginner',study_mode ENUM('Online','Offline','Both') NOT NULL DEFAULT 'Online',creator_id BIGINT UNSIGNED NOT NULL,status ENUM('active','suspended') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL,FOREIGN KEY(creator_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(status,created_at)) ENGINE=InnoDB;
CREATE TABLE group_members(group_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,role ENUM('admin','member') NOT NULL DEFAULT 'member',joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(group_id,user_id),FOREIGN KEY(group_id) REFERENCES study_groups(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE study_sessions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(160) NOT NULL,subject VARCHAR(120) NULL,session_date DATE NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,mode ENUM('Online','Offline','Both') NOT NULL DEFAULT 'Online',meeting_link VARCHAR(500) NULL,notes TEXT NULL,group_id BIGINT UNSIGNED NULL,partner_id BIGINT UNSIGNED NULL,created_by BIGINT UNSIGNED NOT NULL,status ENUM('scheduled','cancelled') NOT NULL DEFAULT 'scheduled',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(group_id) REFERENCES study_groups(id) ON DELETE SET NULL,FOREIGN KEY(partner_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE CASCADE,INDEX(session_date,status)) ENGINE=InnoDB;
CREATE TABLE notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,message VARCHAR(255) NOT NULL,link VARCHAR(255) NOT NULL DEFAULT '',is_read TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,is_read,created_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE ratings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,rater_id BIGINT UNSIGNED NOT NULL,ratee_id BIGINT UNSIGNED NOT NULL,rating TINYINT UNSIGNED NOT NULL,feedback VARCHAR(500) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY one_rating(rater_id,ratee_id),CHECK(rating BETWEEN 1 AND 5),FOREIGN KEY(rater_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(ratee_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE reports(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reporter_id BIGINT UNSIGNED NOT NULL,reported_id BIGINT UNSIGNED NOT NULL,reason ENUM('Inappropriate behavior','Spam','Fake profile','Harassment','Other') NOT NULL,description TEXT NULL,status ENUM('Pending','Reviewed','Resolved','Dismissed') NOT NULL DEFAULT 'Pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(status,created_at),FOREIGN KEY(reporter_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(reported_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
